const visual = {
  prepare: function (input) {
    var texts = ['单位换算表', '90 km/h 换算为 m/s（除以 3.6）', '项目', '内容', '已知量', '90 km/h', '换算关系', '1 m/s = 3.6 km/h，故除以 3.6', '换算算式', '90 ÷ 3.6 = 25', '结果（三位有效数字）', '25.0 m/s'];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.max(28, w * 0.07);
    var tableX = margin;
    var tableY = Math.max(92, h * 0.22);
    var tableW = w - margin * 2;
    var tableH = Math.min(Math.max(200, h - tableY - 36), 260);
    var headerH = 42;
    var rowH = (tableH - headerH) / 4;
    var labelX = tableX + 24;
    var valueX = tableX + tableW * 0.32;
    var headerY = tableY + headerH / 2 + 6;
    var paths = [];
    var lineNodes = [];
    var addLine = function (points, id) {
      paths.push({ id: id, commands: visualSdk.polyline(points) });
      lineNodes.push({ type: 'path', pathId: id, stroke: '#2f3b4a', strokeWidth: 2, fill: 'none' });
    };
    addLine([[tableX, tableY], [tableX + tableW, tableY], [tableX + tableW, tableY + tableH], [tableX, tableY + tableH], [tableX, tableY]], 'border');
    addLine([[tableX, tableY + headerH], [tableX + tableW, tableY + headerH]], 'header-sep');
    addLine([[valueX - 12, tableY], [valueX - 12, tableY + tableH]], 'col-sep');
    for (var i = 1; i < 4; i += 1) {
      var sy = tableY + headerH + rowH * i;
      addLine([[tableX, sy], [tableX + tableW, sy]], 'row-sep-' + i);
    }
    var children = [];
    for (var p = 0; p < lineNodes.length; p += 1) { children.push(lineNodes[p]); }
    children.push({ type: 'label', text: '单位换算表', x: w / 2, y: 42, fontSize: 24, fontWeight: 600, align: 'middle', baseline: 'middle', fill: '#1f2d3d' });
    children.push({ type: 'label', text: '90 km/h 换算为 m/s（除以 3.6）', x: w / 2, y: 70, fontSize: 16, align: 'middle', baseline: 'middle', fill: '#44546a' });
    children.push({ type: 'label', text: '项目', x: labelX, y: headerY, fontSize: 16, fontWeight: 600, fill: '#1f2d3d' });
    children.push({ type: 'label', text: '内容', x: valueX, y: headerY, fontSize: 16, fontWeight: 600, fill: '#1f2d3d' });
    var rowLabels = ['已知量', '换算关系', '换算算式', '结果（三位有效数字）'];
    var rowValues = ['90 km/h', '1 m/s = 3.6 km/h，故除以 3.6', '90 ÷ 3.6 = 25', '25.0 m/s'];
    for (var r = 0; r < 4; r += 1) {
      var ry = tableY + headerH + rowH * (r + 0.5) + 6;
      children.push({ type: 'label', text: rowLabels[r], x: labelX, y: ry, fontSize: 16, fill: '#1f2d3d' });
      children.push({ type: 'label', text: rowValues[r], x: valueX, y: ry, fontSize: 15, fill: '#1f2d3d' });
    }
    return { schemaVersion: 1, sceneId: 'unit-conversion-table', revision: input.revision, viewBox: { x: 0, y: 0, width: w, height: h }, paths: paths, root: { type: 'group', children: children } };
  }
};
